<?php if ( ! defined( 'ABSPATH' ) ) { exit; }
$id = absint( $_GET['post_id'] ?? $_GET['edit_submission'] ?? 0 ); $note = $id ? Revayat_Companion_Member_Notes::get( $id, $args['user']->ID ) : null;
if ( $id && ! $note ) { echo '<p class="rv-member-notice">یادداشت در دسترس نیست.</p>'; return; }
$version = $note ? (int) get_post_meta( $id, '_rv_note_version', true ) : 0;
$editable = ! $note || 'draft' === $note->post_status;
$feedback = $note ? get_post_meta( $id, '_revayat_editorial_note', true ) : '';
if ( $feedback ) { echo '<div class="rv-member-notice"><strong>پیام تحریریه</strong><p>' . esc_html( $feedback ) . '</p></div>'; }
?>
<?php if ( ! $editable ) : ?><article class="rv-member-card"><span class="rv-member-badge">در انتظار بررسی</span><h2><?php echo esc_html( $note->post_title ); ?></h2><div><?php echo wp_kses_post( wpautop( $note->post_content ) ); ?></div><p>تا پایان بررسی، ویرایش قفل است. برای اصلاح، یادداشت را به پیش‌نویس برگردانید.</p><form data-rv-form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="revayat_member_note"><?php wp_nonce_field( 'rv_member_note', 'rv_nonce' ); ?><input type="hidden" name="post_id" value="<?php echo esc_attr( $id ); ?>"><input type="hidden" name="version" value="<?php echo esc_attr( $version ); ?>"><input type="hidden" name="request_key" value="<?php echo esc_attr( wp_generate_uuid4() ); ?>"><button class="rv-member-secondary" name="mode" value="withdraw">بازگشت به پیش‌نویس</button><p data-form-status role="status" hidden></p></form></article>
<?php else : $fields = get_terms( array( 'taxonomy' => 'analyst_field', 'hide_empty' => false ) ); $selected = $note ? wp_get_object_terms( $id, 'analyst_field', array( 'fields' => 'ids' ) ) : array(); ?>
<form class="rv-member-card rv-member-form" data-rv-form data-dirty-guard data-note-editor method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="revayat_member_note"><?php wp_nonce_field( 'rv_member_note', 'rv_nonce' ); ?><input type="hidden" name="post_id" value="<?php echo esc_attr( $id ); ?>"><input type="hidden" name="version" value="<?php echo esc_attr( $version ); ?>"><input type="hidden" name="request_key" value="<?php echo esc_attr( wp_generate_uuid4() ); ?>">
<label>عنوان یادداشت<input name="post_title" required minlength="5" maxlength="200" value="<?php echo esc_attr( $note->post_title ?? '' ); ?>"></label>
<label>موضوع<select name="analyst_field"><option value="0">انتخاب موضوع</option><?php if ( ! is_wp_error( $fields ) ) { foreach ( $fields as $field ) { echo '<option value="' . esc_attr( $field->term_id ) . '" ' . selected( in_array( $field->term_id, $selected, true ), true, false ) . '>' . esc_html( $field->name ) . '</option>'; } } ?></select></label>
<label for="rv-note-content">متن یادداشت</label><?php wp_editor( $note->post_content ?? '', 'rv-note-content', array( 'textarea_name' => 'post_content', 'media_buttons' => false, 'textarea_rows' => 14, 'teeny' => true, 'quicktags' => false ) ); ?>
<label>خلاصه (اختیاری)<textarea name="post_excerpt" rows="3" maxlength="1500"><?php echo esc_textarea( $note->post_excerpt ?? '' ); ?></textarea></label>
<p class="rv-member-help">پیش‌نویس فقط برای شماست. ارسال برای بررسی، متن را تا تصمیم تحریریه قفل می‌کند. حداقل متن برای ارسال ۵۰ نویسه است.</p><p data-form-status role="status" hidden></p><div class="rv-member-actions"><button class="rv-member-secondary" name="mode" value="draft" formnovalidate>ذخیره پیش‌نویس</button><button class="rv-member-button" name="mode" value="submit">ارسال برای بررسی</button></div></form>
<?php endif; ?>
